from paging import sliding_window

def test_window_full_length():
    assert sliding_window([1, 2, 3], 3) == [[1, 2, 3]]

def test_window_larger_than_list():
    assert sliding_window([1], 5) == []

def test_window_one():
    assert sliding_window([1, 2], 1) == [[1], [2]]


